import { AbstractEvent } from './abstract-event';

export class Event3<T1, T2, T3> extends AbstractEvent {
    public addListener(listener: (arg1: T1, arg2: T2, arg3: T3) => void, context?: any): void {
        this.addListenerNode(listener, context, false);
    }

    public addListenerOnce(listener: (arg1: T1, arg2: T2, arg3: T3) => void, context?: any): void {
        this.addListenerNode(listener, context, true);
    }

    public removeListener(listener: (arg1: T1, arg2: T2, arg3: T3) => void): void {
        super.removeListener(listener);
    }

    public dispatch(arg1: T1, arg2: T2, arg3: T3): void {
        this.state.dispatchEvent(arg1, arg2, arg3);
    }
}
